257	              export NIX_SSL_CERT_FILE="${pkgs.cacert}/etc/ssl/certs/ca-bundle.crt"
258	
259	              exec home-manager switch --no-write-lock-file --refresh --flake "$TARGET"
260	            '';
261	          in
262	          {
263	            enable = true;
264	            config = {
265	              ProgramArguments = [ "${upgradeScript}" ];
266	              StartCalendarInterval = [
267	                {
268	                  Hour = 10;
269	                  Minute = 0;
270	                } # Run daily at 10:00 AM
271	              ];
272	              StandardOutPath = "/tmp/cosmo-home-autoupgrade.out.log";
273	              StandardErrorPath = "/tmp/cosmo-home-autoupgrade.err.log";
274	            };
275	          }
